import{z as i,x as s,o as d,c as n,q as l,j as r,D as a,d as e,s as B,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"迭代之间该看哪几个数","description":"","frontmatter":{"title":"迭代之间该看哪几个数","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/closure-metrics.md","filePath":"llm/closure-metrics.md","lastUpdated":1791063341000}'),h={name:"llm/closure-metrics.md"};function p(m,t,u,F,C,D){const A=s("Mermaid");return d(),n("div",null,[t[2]||(t[2]=l('<h1 id="迭代之间该看哪几个数" tabindex="-1">迭代之间该看哪几个数 <a class="header-anchor" href="#迭代之间该看哪几个数" aria-label="Permalink to &quot;迭代之间该看哪几个数&quot;">​</a></h1><div class="epigraph"><p>闭环最难的不是转起来，而是知道它转对了没有；一张跨轮可比、对失效模式正交的仪表，胜过十条训练曲线。</p><footer>—— Gao 等, Scaling Laws for Reward Model Overoptimization（2023）；Shumailov 等, AI models collapse when trained on recursively generated data, Nature（2024）</footer></div><p><a href="/llm/contamination-loop">上一课</a>说明污染能让验证通过率自己上涨；再往前，本课程逐课清点了循环依赖、弱监督天花板、蒸馏与探索的错配、对手选择过拟合。本课收束于此：把失效清单换算成迭代之间该盯的少数几个数。训练损失在这里没有意义——数据分布每轮都在移动；聚合榜单会被污染与饱和拖平。需要的是一组各管一种失效、可跨轮比较的读数。本课收束「自训练与数据闭环」课程；后课默认已读完本课程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最小集合要覆盖四类失效：能力没有真涨（记忆或虚高）、泛化没有外溢（过拟合闭环分布）、多样性在收缩（坍缩前兆）、信号在被钻（验证器与奖励失真）。只盯一项都会误报或漏报：通过率涨可能是污染，多样性稳可能是停滞，奖励涨可能正处在过优化中段——Gao 等人的核心发现就是代理奖励与金标真值随 KL 增大先同涨、后分叉，金标先升后降。所以仪表的单位不是「一个总分」，而是「一组互不冗余的读数」，每项读数要能指认它抓的是哪一类失效。</p><p><span class="marginnote">「正交」原是几何词：两根轴互相垂直、各量各的方向，谁也替代不了谁。用在仪表上，意思是每项读数专门盯一种失效，别的读数涨跌都干扰不到它。这样任何一项报警，你都能直接指认「是哪种失效在发生」，而不是笼统地知道「分数变了」再满头大汗地排查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>下表按「怎么算 / 危险信号 / 抓什么」给出可执行版本，每轮迭代后全表过一遍：</p><table tabindex="0"><thead><tr><th>读数</th><th>怎么算</th><th>危险信号</th><th>抓什么</th></tr></thead><tbody><tr><td>真实增量</td><td>闭环外新验证题的边际 pass@1，与上轮差分</td><td>增量集中在旧题型；与 held-out 不一致</td><td>记忆替代能力</td></tr><tr><td>Held-out 能力</td><td>私有冻结集逐轮跑分，永不入环</td><td>训练域涨、held-out 平</td><td>过拟合闭环分布</td></tr><tr><td>多样性</td><td>生成样本的 distinct-n / 聚类熵</td><td>熵逐轮收缩</td><td>坍缩前兆</td></tr><tr><td>坍缩读数</td><td>对参考模型的嵌入距离、低频 n-gram 占比</td><td>尾部覆盖掉</td><td>分布收缩</td></tr><tr><td>验证器诚实度</td><td>抽样已通过输出，交程序复核或人审</td><td>假阳率上升</td><td>奖励黑客</td></tr><tr><td>污染探针</td><td>金丝雀补全 + 对基准索引的改写匹配</td><td>命中上升</td><td>评测泄漏</td></tr><tr><td>奖励-真值差</td><td>裁判分与可验证真值的相关</td><td>相关下降、裁判分独涨</td><td>过优化</td></tr></tbody></table><p><span class="marginnote">distinct-n 的具体算法：数一数 \\(N\\) 条生成输出里互不相同的 n-gram 有几种，除以 n-gram 总数。例如 100 条答案共含 1000 个二元词组、其中只有 300 种不同，distinct-2 就是 \\(300/1000=0.3\\)；下一轮即使通过率在涨，这个数却掉到 0.12，也说明模型在大量重复自己——这是坍缩的典型前兆。</span></p>',10)),(d(),r(o,null,{default:a(()=>[B(A,{id:"mermaid-143",class:"mermaid",graph:"flowchart%20TD%0A%20%20ITER%5B%22%E7%AC%AC%20t%20%E8%BD%AE%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20COL%5B%22%E6%94%B6%E6%95%B0%EF%BC%9A%E6%96%B0%E9%AA%8C%E8%AF%81%E9%A2%98%20%2F%20held-out%20%2F%20%E5%85%A8%E9%87%8F%E7%94%9F%E6%88%90%22%5D%0A%20%20COL%20--%3E%20TAB%5B%22%E8%BF%87%E4%B8%83%E9%A1%B9%E8%AF%BB%E6%95%B0%22%5D%0A%20%20TAB%20--%3E%20DEC%7B%22%E4%B8%A4%E9%A1%B9%E5%8F%8A%E4%BB%A5%E4%B8%8A%E6%8A%A5%E8%AD%A6%3F%22%7D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E7%AC%AC%20t%2B1%20%E8%BD%AE%22%5D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20ACT%5B%22%E5%9B%9E%E6%BB%9A%E6%A3%80%E6%9F%A5%E7%82%B9%E6%88%96%E5%81%9C%E6%AD%A2%EF%BC%8C%E5%85%88%E6%9F%A5%E6%B1%A1%E6%9F%93%E6%8E%A2%E9%92%88%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),t[4]||(t[4]=E("p",null,"这组读数的设计逻辑是正交：真实增量管「涨的是不是能力」，held-out 管「涨的是不是泛化」，多样性与尾部管「分布还开不开着」，验证器诚实度、污染探针、奖励-真值差管「信号链有没有断」。本课程各课的失效各自落在某一行：self-rewarding 的循环依赖表现为裁判分独涨而真值差扩大；弱到强的退化对齐表现为 held-out 不动；蒸馏冒充探索表现为增量与教师覆盖完全同分布；污染表现为探针命中。判据要预先钉死：单项报警先复核，两项以上回滚——事后改判据，就是让仪表迁就曲线。",-1)),t[5]||(t[5]=E("p",null,[E("span",{class:"marginnote"},"为什么判据必须在开环前钉死？因为训练曲线永远能找到一种「读法」让自己显得健康。一旦允许事后调整阈值，人总会不知不觉把报警线挪到曲线上方，仪表就退化成装饰品——这与实验科学「先注册假设、再跑实验」以防 p-hacking，是同一条纪律。")],-1)),(d(),r(o,null,{default:a(()=>[B(A,{id:"mermaid-153",class:"mermaid",graph:"flowchart%20LR%0A%20%20F1%5B%22%E5%A4%B1%E6%95%88%E4%B8%80%EF%BC%9A%E8%AE%B0%E5%BF%86%E6%88%96%E8%99%9A%E9%AB%98%22%5D%20--%3E%20R1%5B%22%E7%9C%9F%E5%AE%9E%E5%A2%9E%E9%87%8F%22%5D%0A%20%20F2%5B%22%E5%A4%B1%E6%95%88%E4%BA%8C%EF%BC%9A%E8%BF%87%E6%8B%9F%E5%90%88%E9%97%AD%E7%8E%AF%E5%88%86%E5%B8%83%22%5D%20--%3E%20R2%5B%22Held-out%20%E8%83%BD%E5%8A%9B%22%5D%0A%20%20F3%5B%22%E5%A4%B1%E6%95%88%E4%B8%89%EF%BC%9A%E5%A4%9A%E6%A0%B7%E6%80%A7%E6%94%B6%E7%BC%A9%22%5D%20--%3E%20R3%5B%22%E5%A4%9A%E6%A0%B7%E6%80%A7%20%2B%20%E5%9D%8D%E7%BC%A9%E8%AF%BB%E6%95%B0%22%5D%0A%20%20F4%5B%22%E5%A4%B1%E6%95%88%E5%9B%9B%EF%BC%9A%E4%BF%A1%E5%8F%B7%E8%A2%AB%E9%92%BB%22%5D%20--%3E%20R4%5B%22%E8%AF%9A%E5%AE%9E%E5%BA%A6%20%2F%20%E6%B1%A1%E6%9F%93%E6%8E%A2%E9%92%88%20%2F%20%E5%A5%96%E5%8A%B1-%E7%9C%9F%E5%80%BC%E5%B7%AE%22%5D%0A%20%20R1%20--%3E%20D%5B%22%E4%B8%A4%E9%A1%B9%E4%BB%A5%E4%B8%8A%E6%8A%A5%E8%AD%A6%EF%BC%9A%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20R2%20--%3E%20D%0A%20%20R3%20--%3E%20D%0A%20%20R4%20--%3E%20D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[e(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=l('<p><span class="marginnote">Gao 等人 2023 的过优化定律给出金标读数的位置：随 KL 增大，代理奖励单调涨，金标真值先涨后跌。闭环里「奖励还在涨」永远不是继续迭代的理由，金标侧的峰值才是。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>仪表有成本：每轮全量生成算熵与距离、程序复核抽样，都不便宜，可按轮次抽半。熵类读数依赖聚类数与 n 的取法，跨轮必须冻结实现，否则比较失效。没有仪表能对抗无限期的对抗优化：策略最终会学会绕过任何固定探针，held-out 要定期轮换、部分题目用后即弃。最后，人审切片不可替代——七项读数全绿、但抽样读文本已经千篇一律的闭环，在文献里并不少见。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迭代间最小读数集：真实增量、held-out、多样性、坍缩、验证器诚实度、污染探针、奖励-真值差。</li><li>单项报警先复核，两项以上回滚；判据在开环前钉死。</li><li>「奖励还在涨」不是继续的理由，金标与 held-out 才是。</li><li>仪表会老化：held-out 轮换、探针更新、实现细节跨轮冻结。</li><li>出处：Gao 等（2023）；Shumailov 等（2024）；pass@\\(k\\) 出自 Chen 等 2021；各失效模式见本课程前五课。</li></ul>',5))])}const _=i(h,[["render",p]]);export{f as __pageData,_ as default};
